class Invitation(models.Model):
    id = models.UUIDField(primary_key=True, default=uuid.uuid4, editable=False)
    organization = models.ForeignKey("orgs.Organization", models.CASCADE)
    email = models.CharField(max_length=254)
    role = models.ForeignKey("orgs.Role", models.RESTRICT)
    token_hash = models.CharField(max_length=191, unique=True)
    invited_by_id = models.UUIDField()
    expires_at = models.DateTimeField()
    accepted_at = models.DateTimeField(null=True, blank=True)
    revoked_at = models.DateTimeField(null=True, blank=True)
    created_at = models.DateTimeField(auto_now_add=True)

    class Meta:
        db_table = "invitations"
        indexes = [models.Index(fields=['organization', 'email'], name="invitations_orga_emai")]


class Session(models.Model):
    id = models.UUIDField(primary_key=True, default=uuid.uuid4, editable=False)
    token_hash = models.CharField(max_length=191, unique=True)
    user = models.ForeignKey(settings.AUTH_USER_MODEL, models.CASCADE)
